#!/usr/bin/env python3
"""Eight-scene vector witness: pose, subject gaze and sampled viewer paths."""
import argparse,json
from pathlib import Path
p=argparse.ArgumentParser(description=__doc__);p.add_argument('root',type=Path);p.add_argument('output',type=Path);a=p.parse_args();a.output.mkdir(exist_ok=False)
ids=['selfie-family-hike','birthday-cake-kitchen','vacation-museum-cafe','linen-shirt-model','leather-tote-model','garden-furniture-context','coffee-bar-context','dog-harness-white'];data=[];lookup={r['id']:r for r in json.loads((a.root/'inputs.json').read_text())['images']}
for id in ids:
 row=lookup[id];data.append({'id':id,'width':row['width'],'height':row['height'],'pose':json.loads((a.root/'geometry'/(id+'-pose.json')).read_text())['result']['landmarks'],'gaze':json.loads((a.root/'gaze-all'/(id+'.json')).read_text())['result']['people'],'scan':json.loads((a.root/'scan-all'/(id+'.json')).read_text())['result']['paths'],'image':'http://dev.lan:3300/zensally/runtime-models/2026-11-08/gallery/assets/'+id+'.png'})
html='''<!doctype html><meta charset="utf-8"><title>Pose, gaze and viewer scanpaths</title><style>body{font:16px system-ui;background:#1e2024;color:#eee;margin:24px}main{display:grid;grid-template-columns:repeat(auto-fit,minmax(290px,1fr));gap:20px}article{background:#30343a;padding:14px}svg{width:100%;max-height:500px}label{margin-right:18px}h2{font-size:17px}p{max-width:1100px;line-height:1.45}</style><h1>Pose, subject gaze and viewer scanpaths</h1><p>Eight annotation-only synthetic photographs. Local model predictions, not human measurements or trusted face coverage. Viewer paths are four stochastic alternatives, each with six free fixations; the imposed central starting fixation is omitted. Subject gaze is a different signal: dashed orange arrows have an in-frame score below 0.5. No artistic-crop improvement is claimed.</p><p><label><input type="checkbox" id="pose" checked>Pose</label><label><input type="checkbox" id="gaze" checked>Subject gaze</label><label><input type="checkbox" id="scan">Viewer paths</label></p><main></main><script>const data=DATA;
const edges=[[11,12],[11,13],[13,15],[12,14],[14,16],[11,23],[12,24],[23,24],[23,25],[25,27],[24,26],[26,28]];
function render(){let main=document.querySelector('main');main.innerHTML='';for(const row of data){let el=document.createElement('article');let title=document.createElement('h2');title.textContent=row.id;el.append(title);let svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 1000 '+(1000*row.height/row.width));let H=1000*row.height/row.width;svg.innerHTML='<defs><marker id="arrow" markerWidth="5" markerHeight="5" refX="4" refY="2.5" orient="auto"><path d="M0,0 L5,2.5 L0,5" fill="orange"/></marker></defs><image href="'+row.image+'" width="1000" height="'+H+'"/>';function line(a,b,color,dash=false){let n=document.createElementNS(svg.namespaceURI,'line');for(const [k,v]of Object.entries({x1:a[0]*1000,y1:a[1]*H,x2:b[0]*1000,y2:b[1]*H,stroke:color,'stroke-width':5}))n.setAttribute(k,v);if(dash)n.setAttribute('stroke-dasharray','12 9');svg.append(n);return n}function circle(x,y,color,text){let c=document.createElementNS(svg.namespaceURI,'circle');c.setAttribute('cx',x*1000);c.setAttribute('cy',y*H);c.setAttribute('r',8);c.setAttribute('fill',color);svg.append(c);if(text){let t=document.createElementNS(svg.namespaceURI,'text');t.setAttribute('x',x*1000+9);t.setAttribute('y',y*H);t.setAttribute('fill',color);t.setAttribute('font-size','30');t.textContent=text;svg.append(t)}}
if(document.querySelector('#pose').checked)for(const person of row.pose){let valid=p=>(p.visibility||0)*(p.presence||0)>=.25;for(const[a,b]of edges)if(valid(person[a])&&valid(person[b]))line([person[a].x,person[a].y],[person[b].x,person[b].y],'#3fff75');for(const p of person)if(valid(p))circle(p.x,p.y,'#3fff75')}
if(document.querySelector('#gaze').checked)for(const person of row.gaze){let c=[(person.head[0]+person.head[2])/2,(person.head[1]+person.head[3])/2];let l=line(c,person.target,'orange',person.in_frame_score<.5);l.setAttribute('marker-end','url(#arrow)');circle(...person.target,'orange');}
if(document.querySelector('#scan').checked)row.scan.forEach((path,j)=>{const color=['#ff52ed','#55d7ff','#fff555','#ff6b5b'][j];path.forEach((p,i)=>{if(i)line([path[i-1].x,path[i-1].y],[p.x,p.y],color);circle(p.x,p.y,color,String(i+1))})});el.append(svg);main.append(el)}}for(const el of document.querySelectorAll('input'))el.addEventListener('change',render);render();</script>'''
(a.output/'index.html').write_text(html.replace('DATA',json.dumps(data)));(a.output/'witness.json').write_text(json.dumps({'bounded_witness_sources':ids,'predictions':data,'diagnostic_maps_saved':False},indent=2)+'\n')
print(json.dumps({'sources':len(ids),'html_bytes':(a.output/'index.html').stat().st_size}))
